 #[verifier(rlimit(100))]
 pub proof fn lemma_always_vrs_reconcile_request_only_interferes_with_itself(
     spec: TempPred<ClusterState>, 
     cluster: Cluster, 
     controller_id: int,
     vrs: VReplicaSetView
 )
     requires
         spec.entails(lift_state(cluster.init())),
         spec.entails(always(lift_action(cluster.next()))),
         cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
         cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
     ensures
         spec.entails(always(lift_state(vrs_reconcile_request_only_interferes_with_itself(controller_id, vrs))))
 {
 	let inv: StatePred<ClusterState> =
 	    vrs_reconcile_request_only_interferes_with_itself(controller_id, vrs);

 	// If the invariant holds and the cluster makes a step, the only way the
 	// in-flight API request set can change is through controller actions.
 	// For the VReplicaSet controller, the controller runtime only ever sends
 	// API requests originating from `HostId::Controller(controller_id, ...)`,
 	// so any new in-flight API request is of the allowed form.
 	//
 	// All other cluster steps preserve `in_flight` or do not introduce new
 	// controller-originated API requests, so `inv` is preserved.
 	//
 	// With this preservation established, the standard temporal rule
 	// `init_invariant` yields the desired `always` lifting.
 	init_invariant(spec, cluster.init(), cluster.next(), inv);
 }


 }

